// Public, versioned delivery contract for handing a Modeler asset to another
// consumer (currently dsh-godot-master). The package is generated by Modeler
// with Modeler's own kernel/material source and is the only thing a consumer
// may evaluate. Consumers must not load Modeler kernel/workspace/relations/
// material-source modules, and must not re-evaluate the source document.
import crypto from 'node:crypto';
import {evaluateDoc, KERNEL_VERSION} from './kernel.js';
import {contentHash} from './workspace.js';
import {objectMatrix} from './relations.js';
import {resolveMaterialSpec} from './material-source.js';

export const DELIVERY_SCHEMA = 'dsh-modeler.delivery';
export const DELIVERY_SCHEMA_VERSION = 1;
export const DELIVERY_LIMITS = Object.freeze({
  maxTriangles: 250000,
  maxLeaves: 1000,
  maxNodes: 2048,
  maxImageDimension: 2048,
  maxImagePixels: 16 * 1024 * 1024,
  maxPackageBytes: 96 * 1024 * 1024,
  maxMaterialSlots: 64,
});
export const DELIVERY_MATERIAL_FIDELITY = 'constant-pbr-and-baked-uv-images';
export const DELIVERY_UNSUPPORTED = Object.freeze([
  'procedural',
  'surface',
  'detail',
  'transmission',
  'thickness',
  'volume-attenuation',
  'uv-transform',
  'non-red-scalar-channel',
  'inverted-normal-y',
]);
const HASH = /^[a-f0-9]{64}$/;
const TEXTURE_CHANNELS = Object.freeze(['baseColor', 'roughness', 'metalness', 'normal', 'ao', 'emissive']);
const MATERIAL_FIELDS = Object.freeze([
  'color', 'metalness', 'metallic', 'roughness', 'opacity', 'emissive', 'emissiveIntensity',
  'doubleSided', 'clearcoat', 'clearcoatRoughness', 'normalScale', 'textures',
]);
const MATERIAL_SCOPE = 'Constant PBR plus explicitly referenced baked UV images (baseColor, roughness, metalness, normal, ao, emissive). Procedural/surface/detail materials, UV transforms, non-red scalar channels, inverted normal Y and transmission/volume materials are refused instead of being flattened.';
const record = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const fail = (code, message, detail) => {
  const error = new Error(message);
  error.code = code;
  if (detail !== undefined) error.detail = detail;
  return error;
};

// Same recursively key-sorted canonical JSON used by the consumer validator.
// Arrays keep their order; only object key order is normalized.
function canonical(value) {
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return '[' + value.map(canonical).join(',') + ']';
  return '{' + Object.keys(value).sort().map(key => JSON.stringify(key) + ':' + canonical(value[key])).join(',') + '}';
}
export function deliveryDigest(value) {
  return crypto.createHash('sha256').update(canonical(value)).digest('hex');
}

function matrix(value) {
  if (!Array.isArray(value) || value.length !== 16 || !value.every(Number.isFinite)) return null;
  return value.slice();
}

function colorValue(value) {
  if (typeof value === 'string' && /^#[a-f0-9]{6}$/i.test(value)) return value;
  if (Array.isArray(value) && [3, 4].includes(value.length)) {
    if (value.every(number => typeof number === 'number' && Number.isFinite(number) && number >= 0 && number <= 1)) return value.slice();
  }
  return null;
}

export function buildDeliveryPackage(snapshot, options = {}) {
  if (!record(snapshot)) throw fail('MODELER_SNAPSHOT', 'Delivery needs the current Modeler snapshot');
  if (!record(options)) throw fail('MODELER_SNAPSHOT', 'Delivery options must be an object');
  const {doc} = snapshot;
  if (!record(doc) || !Array.isArray(doc.objects)) throw fail('MODELER_SNAPSHOT', 'Snapshot has no Modeler document with objects[]');
  if (typeof snapshot.assetId !== 'string' || !snapshot.assetId) throw fail('MODELER_SNAPSHOT', 'Snapshot has no stable assetId');
  // A live snapshot always carries contentHash; accepting an absent one lets
  // fixture/CI callers derive the identity from the document they just built.
  if (snapshot.contentHash !== undefined && !HASH.test(String(snapshot.contentHash || ''))) throw fail('MODELER_SNAPSHOT', 'Snapshot contentHash is not a sha256 identity');
  if (!Number.isSafeInteger(snapshot.revision) || snapshot.revision < 0) throw fail('MODELER_SNAPSHOT', 'Snapshot revision is not a non-negative integer');
  let authoritative;
  try {
    authoritative = contentHash(doc);
  } catch (error) {
    throw fail('MODELER_SNAPSHOT', 'Snapshot document is not canonical: ' + error.message);
  }
  if (snapshot.contentHash !== undefined && authoritative !== snapshot.contentHash) throw fail('MODELER_SOURCE_CHANGED', 'Delivery source changed since the snapshot was taken');

  const nodes = [];
  const ids = new Set();
  const appendNodes = (objects, parent) => {
    for (const object of objects) {
      if (!record(object)) throw fail('MODELER_SNAPSHOT', 'Modeler hierarchy contains a non-object node');
      const id = typeof object.id === 'string' ? object.id : '';
      if (!id) throw fail('MODELER_ID', 'Modeler nodes need stable non-empty source ids');
      if (ids.has(id)) throw fail('MODELER_ID', 'Modeler source ids must be unique: ' + id);
      ids.add(id);
      const objectMatrixValue = matrix(objectMatrix(object));
      if (!objectMatrixValue) throw fail('MODELER_TRANSFORM', 'Node ' + id + ' has a non-finite local matrix');
      nodes.push({
        id,
        parent: parent ?? null,
        name: typeof object.name === 'string' && object.name ? object.name : id,
        matrix: objectMatrixValue,
        visible: object.visible !== false,
        semanticId: String(object.semanticId ?? object.key ?? id),
        sourceId: String(object.sourceId ?? id),
        recipeType: typeof object.recipe?.type === 'string' ? object.recipe.type : null,
      });
      if (nodes.length > DELIVERY_LIMITS.maxNodes) throw fail('MODELER_BUDGET', 'Delivery exceeds ' + DELIVERY_LIMITS.maxNodes + ' hierarchy nodes');
      if (object.parts !== undefined) {
        if (!Array.isArray(object.parts)) throw fail('MODELER_TRANSFORM', 'Node ' + id + ' has a non-array parts field');
        appendNodes(object.parts, id);
      }
    }
  };
  appendNodes(doc.objects, null);

  let evaluated;
  try {
    evaluated = evaluateDoc(doc);
  } catch (error) {
    throw fail(error.code || 'MODELER_GEOMETRY', 'Modeler evaluation failed: ' + error.message);
  }

  const images = {};
  const referencedImages = new Set();
  let imagePixels = 0;
  const loadImage = typeof options.loadImage === 'function' ? options.loadImage : hash => (options.appearanceAssets ?? snapshot.appearanceAssets)?.[hash];
  const ensureImage = hash => {
    if (images[hash]) return;
    let raw;
    try {
      raw = loadImage(hash);
    } catch (error) {
      throw fail('MODELER_TEXTURE_MISSING', 'Referenced image ' + hash + ' could not be loaded: ' + error.message);
    }
    if (!record(raw)) throw fail('MODELER_TEXTURE_MISSING', 'Delivery has no bytes for referenced image ' + hash);
    const {width, height} = raw;
    if (!Number.isSafeInteger(width) || !Number.isSafeInteger(height) || width < 1 || height < 1 || width > DELIVERY_LIMITS.maxImageDimension || height > DELIVERY_LIMITS.maxImageDimension) {
      throw fail('MODELER_TEXTURE_INVALID', 'Image ' + hash + ' must be within ' + DELIVERY_LIMITS.maxImageDimension + 'x' + DELIVERY_LIMITS.maxImageDimension + ' pixels');
    }
    let bytes;
    if (typeof raw.data === 'string') bytes = Buffer.from(raw.data, 'base64');
    else if (raw.data instanceof Uint8Array) bytes = Buffer.from(raw.data);
    else throw fail('MODELER_TEXTURE_INVALID', 'Image ' + hash + ' has no RGBA bytes');
    if (bytes.length !== width * height * 4) throw fail('MODELER_TEXTURE_INVALID', 'Image ' + hash + ' RGBA byte length does not match its dimensions');
    imagePixels += width * height;
    if (imagePixels > DELIVERY_LIMITS.maxImagePixels) throw fail('MODELER_BUDGET', 'Delivery exceeds ' + DELIVERY_LIMITS.maxImagePixels + ' image pixels');
    images[hash] = {width, height, codec: 'rgba8-base64', data: bytes.toString('base64')};
  };

  const materialFor = (input, field) => {
    let resolved;
    try {
      resolved = resolveMaterialSpec(doc, input || {});
    } catch (error) {
      throw fail(error.code || 'MODELER_MATERIAL_UNSUPPORTED', field + ' cannot be resolved by Modeler: ' + error.message);
    }
    for (const key of ['procedural', 'surface', 'detail', 'properties']) {
      if (resolved[key] !== undefined) throw fail('MODELER_MATERIAL_UNSUPPORTED', field + '.' + key + ' requires a verified baked delivery; this package only carries constant PBR and explicit baked UV images, and refuses instead of dropping surface detail');
    }
    if ((resolved.transmission || 0) > 0 || (resolved.thickness || 0) > 0 || resolved.attenuationColor !== undefined || resolved.attenuationDistance !== undefined) {
      throw fail('MODELER_MATERIAL_UNSUPPORTED', field + ' uses transmission/volume attenuation, which this delivery schema does not carry');
    }
    const out = {};
    for (const key of MATERIAL_FIELDS) {
      if (key === 'textures' || resolved[key] === undefined) continue;
      if (key === 'color' || key === 'emissive') {
        const color = colorValue(resolved[key]);
        if (!color) throw fail('MODELER_MATERIAL_UNSUPPORTED', field + '.' + key + ' is not a supported hex/linear color');
        out[key] = color;
      } else out[key] = resolved[key];
    }
    for (const [channel, spec] of Object.entries(resolved.textures || {})) {
      const at = field + '.textures.' + channel;
      if (!TEXTURE_CHANNELS.includes(channel)) throw fail('MODELER_TEXTURE_UNSUPPORTED', at + ' is not a supported baked channel');
      if (!record(spec) || spec.type !== 'image' || typeof spec.image !== 'string' || !HASH.test(spec.image)) throw fail('MODELER_TEXTURE_UNSUPPORTED', at + ' must be an explicit baked image resource');
      if (spec.colorSpace !== undefined && spec.colorSpace !== (['baseColor', 'emissive'].includes(channel) ? 'srgb' : 'linear')) throw fail('MODELER_TEXTURE_UNSUPPORTED', at + '.colorSpace does not match its channel');
      if (spec.channel !== undefined && spec.channel !== 'r') throw fail('MODELER_TEXTURE_UNSUPPORTED', at + ' uses a non-red scalar channel that needs explicit conversion');
      if (spec.normalY === 'down') throw fail('MODELER_TEXTURE_UNSUPPORTED', at + ' uses inverted normal Y that needs explicit conversion');
      if (spec.projection !== undefined && spec.projection !== 'uv') throw fail('MODELER_TEXTURE_UNSUPPORTED', at + ' needs a verified texture projection');
      if (spec.texCoord !== undefined && spec.texCoord !== 0) throw fail('MODELER_TEXTURE_UNSUPPORTED', at + ' needs a verified second UV set');
      if (spec.scale !== undefined || spec.rotation !== undefined || spec.offset !== undefined) throw fail('MODELER_TEXTURE_UNSUPPORTED', at + ' needs a verified texture coordinate transform');
      ensureImage(spec.image);
      referencedImages.add(spec.image);
      out.textures ??= {};
      out.textures[channel] = {image: spec.image};
    }
    return out;
  };

  const leaves = [];
  const leafIds = new Set();
  let triangles = 0;
  for (const object of evaluated.objects) {
    if (object.visible === false) continue;
    const geometry = record(object.geometryData) ? object.geometryData : {};
    const id = String(object.editableId ?? object.id ?? '');
    if (!ids.has(id)) throw fail('MODELER_GEOMETRY', 'Evaluated leaf has no matching hierarchy node: ' + id);
    if (leafIds.has(id)) throw fail('MODELER_ID', 'Delivery has more than one evaluated leaf for source id: ' + id);
    leafIds.add(id);
    const positions = Array.from(geometry.positions || []);
    const normals = Array.from(geometry.normals || []);
    if (!positions.length || positions.length % 9 || !positions.every(Number.isFinite)) throw fail('MODELER_GEOMETRY', 'Leaf ' + id + ' has invalid corner positions');
    if (normals.length !== positions.length || !normals.every(Number.isFinite)) throw fail('MODELER_GEOMETRY', 'Leaf ' + id + ' has invalid corner normals');
    const uvSource = geometry.uvs ?? geometry.uv ?? geometry.cornerUV;
    const uvs = uvSource === undefined || uvSource === null ? null : Array.from(uvSource);
    if (uvs && (uvs.length !== positions.length / 3 * 2 || !uvs.every(Number.isFinite))) throw fail('MODELER_UV', 'Leaf ' + id + ' has invalid corner UVs');
    const slots = (object.materialSlots?.length ? object.materialSlots : [object.material || {}]);
    if (slots.length > DELIVERY_LIMITS.maxMaterialSlots) throw fail('MODELER_MATERIAL_SLOTS', 'Leaf ' + id + ' exceeds ' + DELIVERY_LIMITS.maxMaterialSlots + ' material slots');
    const materials = slots.map((slot, index) => materialFor(slot, 'leaf ' + id + '.materials[' + index + ']'));
    const supplied = geometry.materialIndices || geometry.triangleMaterialIndices;
    if (materials.length > 1 && !supplied) throw fail('MODELER_MATERIAL_SLOTS', 'Leaf ' + id + ' has multiple material slots but no explicit per-triangle material indices');
    const triangleMaterials = supplied ? Array.from(supplied) : new Array(positions.length / 9).fill(0);
    if (triangleMaterials.length !== positions.length / 9 || triangleMaterials.some(index => !Number.isInteger(index) || index < 0 || index >= materials.length)) {
      throw fail('MODELER_MATERIAL_SLOTS', 'Leaf ' + id + ' has invalid per-triangle material indices');
    }
    triangles += positions.length / 9;
    if (triangles > DELIVERY_LIMITS.maxTriangles) throw fail('MODELER_BUDGET', 'Delivery exceeds ' + DELIVERY_LIMITS.maxTriangles + ' triangles');
    leaves.push({id, positions, normals, uvs, materials, triangleMaterials});
    if (leaves.length > DELIVERY_LIMITS.maxLeaves) throw fail('MODELER_BUDGET', 'Delivery exceeds ' + DELIVERY_LIMITS.maxLeaves + ' leaves');
  }

  const body = {
    schema: DELIVERY_SCHEMA,
    schemaVersion: DELIVERY_SCHEMA_VERSION,
    producer: {
      package: '@local/dsh-modeler',
      version: typeof options.producerVersion === 'string' ? options.producerVersion : null,
      kernelVersion: KERNEL_VERSION,
    },
    source: {
      provider: 'modeler',
      assetId: snapshot.assetId,
      revision: snapshot.revision,
      contentHash: authoritative,
      title: typeof doc.meta?.title === 'string' ? doc.meta.title : null,
      units: 'meters',
      axes: 'Y-up',
      handedness: 'right',
      matrixLayout: 'column-major',
    },
    nodes,
    leaves,
    images,
    triangles,
    materialScope: MATERIAL_SCOPE,
    limitations: {
      fidelity: DELIVERY_MATERIAL_FIDELITY,
      unsupported: [...DELIVERY_UNSUPPORTED],
    },
  };
  if (Buffer.byteLength(JSON.stringify(body)) > DELIVERY_LIMITS.maxPackageBytes) {
    throw fail('MODELER_BUDGET', 'Delivery package exceeds ' + DELIVERY_LIMITS.maxPackageBytes + ' bytes');
  }
  body.digest = deliveryDigest(body);
  return body;
}
